import { Pool } from "pg";
import { PrismaPg } from "@prisma/adapter-pg";
import { PrismaClient } from "@/generated/prisma/client";

const globalForPrisma = globalThis as unknown as { prisma: PrismaClient };

const connectionString = process.env.DATABASE_URL;
const pool = new Pool({ connectionString });
const adapter = new PrismaPg(pool);

export const prisma =
  globalForPrisma.prisma || new PrismaClient({ adapter });

if (process.env.NODE_ENV !== "production") {
  globalForPrisma.prisma = prisma;
}

-- ============================================================================
-- Migration: Row Level Security (RLS) & Storage Access Control
-- Strict enforcement of the Data API permission matrix and private storage
-- ============================================================================

-- ─── 1. Security Definer Helpers ────────────────────────────────────────────
-- Helper functions allow clean, efficient, and recursion-safe policy evaluation.
-- They execute with owner privileges and a fixed search_path.

CREATE OR REPLACE FUNCTION public.get_user_org_id()
RETURNS UUID
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = public
AS $$
  SELECT org_id FROM memberships WHERE user_id = auth.uid() LIMIT 1;
$$;

CREATE OR REPLACE FUNCTION public.get_user_role()
RETURNS member_role
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = public
AS $$
  SELECT role FROM memberships WHERE user_id = auth.uid() LIMIT 1;
$$;

CREATE OR REPLACE FUNCTION public.get_tenant_org_id()
RETURNS UUID
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = public
AS $$
  SELECT org_id FROM tenants WHERE user_id = auth.uid() LIMIT 1;
$$;

CREATE OR REPLACE FUNCTION public.get_tenant_id()
RETURNS UUID
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = public
AS $$
  SELECT id FROM tenants WHERE user_id = auth.uid() LIMIT 1;
$$;

CREATE OR REPLACE FUNCTION public.is_org_manager(target_org_id UUID)
RETURNS BOOLEAN
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = public
AS $$
  SELECT EXISTS (
    SELECT 1 FROM memberships
    WHERE user_id = auth.uid()
      AND org_id = target_org_id
      AND role = 'manager'
  );
$$;

CREATE OR REPLACE FUNCTION public.extract_org_id_from_path(path text)
RETURNS UUID
LANGUAGE plpgsql
IMMUTABLE
AS $$
DECLARE
  first_part text;
BEGIN
  first_part := split_part(path, '/', 1);
  IF first_part ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
    RETURN first_part::uuid;
  ELSE
    RETURN NULL;
  END IF;
END;
$$;

-- Grant execute on helpers to authenticated users
GRANT EXECUTE ON FUNCTION public.get_user_org_id() TO authenticated;
GRANT EXECUTE ON FUNCTION public.get_user_role() TO authenticated;
GRANT EXECUTE ON FUNCTION public.get_tenant_org_id() TO authenticated;
GRANT EXECUTE ON FUNCTION public.get_tenant_id() TO authenticated;
GRANT EXECUTE ON FUNCTION public.is_org_manager(UUID) TO authenticated;
GRANT EXECUTE ON FUNCTION public.extract_org_id_from_path(text) TO authenticated;

-- ─── 2. SQL Privilege Lockdown ──────────────────────────────────────────────
-- "Every other insert, update or delete through the Data API must fail for everyone."
-- "Any table that anonymous users can read or write through the Data API -> Instant Fail."

-- Revoke all table permissions from anon and public
REVOKE ALL ON ALL TABLES IN SCHEMA public FROM anon, public;
REVOKE ALL ON ALL SEQUENCES IN SCHEMA public FROM anon, public;
REVOKE ALL ON ALL ROUTINES IN SCHEMA public FROM anon, public;

-- Revoke all table permissions from authenticated by default
REVOKE ALL ON ALL TABLES IN SCHEMA public FROM authenticated;

-- Explicitly GRANT only the minimum required permissions to authenticated
GRANT SELECT ON organizations TO authenticated;
GRANT SELECT ON memberships TO authenticated;
GRANT SELECT ON units TO authenticated;
GRANT SELECT ON leases TO authenticated;
GRANT SELECT ON invoices TO authenticated;
GRANT SELECT ON payments TO authenticated;
GRANT SELECT ON payment_allocations TO authenticated;
GRANT SELECT ON gateway_bills TO authenticated;
GRANT SELECT ON audit_log TO authenticated;

-- On tenants, grant SELECT and strictly UPDATE only on the phone column
GRANT SELECT ON tenants TO authenticated;
GRANT UPDATE (phone) ON tenants TO authenticated;

-- ─── 3. Row Level Security Policies ─────────────────────────────────────────

-- 1. Organizations
-- Tenant, Staff, Manager: read own organization
DROP POLICY IF EXISTS "organizations_select" ON organizations;
CREATE POLICY "organizations_select" ON organizations
FOR SELECT TO authenticated
USING (
  id = public.get_user_org_id() OR id = public.get_tenant_org_id()
);

-- 2. Memberships
-- Tenant: none. Staff, Manager: read own organization
DROP POLICY IF EXISTS "memberships_select" ON memberships;
CREATE POLICY "memberships_select" ON memberships
FOR SELECT TO authenticated
USING (
  org_id = public.get_user_org_id()
);

-- 3. Units
-- Staff, Manager: read own organization
-- Tenant: read the units of own leases
DROP POLICY IF EXISTS "units_select" ON units;
CREATE POLICY "units_select" ON units
FOR SELECT TO authenticated
USING (
  org_id = public.get_user_org_id()
  OR
  EXISTS (
    SELECT 1 FROM leases
    WHERE leases.unit_id = units.id
      AND leases.tenant_id = public.get_tenant_id()
  )
);

-- 4. Tenants
-- Staff, Manager: read own organization
-- Tenant: read own row, update only phone
DROP POLICY IF EXISTS "tenants_select" ON tenants;
CREATE POLICY "tenants_select" ON tenants
FOR SELECT TO authenticated
USING (
  org_id = public.get_user_org_id()
  OR
  user_id = auth.uid()
);

DROP POLICY IF EXISTS "tenants_update_phone" ON tenants;
CREATE POLICY "tenants_update_phone" ON tenants
FOR UPDATE TO authenticated
USING (
  user_id = auth.uid()
)
WITH CHECK (
  user_id = auth.uid()
);

-- 5. Leases
-- Staff, Manager: read own organization
-- Tenant: read rows of own leases
DROP POLICY IF EXISTS "leases_select" ON leases;
CREATE POLICY "leases_select" ON leases
FOR SELECT TO authenticated
USING (
  org_id = public.get_user_org_id()
  OR
  tenant_id = public.get_tenant_id()
);

-- 6. Invoices
-- Staff, Manager: read own organization
-- Tenant: read rows of own leases
DROP POLICY IF EXISTS "invoices_select" ON invoices;
CREATE POLICY "invoices_select" ON invoices
FOR SELECT TO authenticated
USING (
  org_id = public.get_user_org_id()
  OR
  EXISTS (
    SELECT 1 FROM leases
    WHERE leases.id = invoices.lease_id
      AND leases.tenant_id = public.get_tenant_id()
  )
);

-- 7. Payments
-- Staff, Manager: read own organization
-- Tenant: read rows of own leases
DROP POLICY IF EXISTS "payments_select" ON payments;
CREATE POLICY "payments_select" ON payments
FOR SELECT TO authenticated
USING (
  org_id = public.get_user_org_id()
  OR
  EXISTS (
    SELECT 1 FROM leases
    WHERE leases.id = payments.lease_id
      AND leases.tenant_id = public.get_tenant_id()
  )
);

-- 8. Payment Allocations
-- Staff, Manager: read own organization
-- Tenant: read rows of own leases
DROP POLICY IF EXISTS "payment_allocations_select" ON payment_allocations;
CREATE POLICY "payment_allocations_select" ON payment_allocations
FOR SELECT TO authenticated
USING (
  org_id = public.get_user_org_id()
  OR
  EXISTS (
    SELECT 1 FROM payments
    JOIN leases ON leases.id = payments.lease_id
    WHERE payments.id = payment_allocations.payment_id
      AND leases.tenant_id = public.get_tenant_id()
  )
);

-- 9. Gateway Bills
-- Staff, Manager: read own organization
-- Tenant: read rows of own leases
DROP POLICY IF EXISTS "gateway_bills_select" ON gateway_bills;
CREATE POLICY "gateway_bills_select" ON gateway_bills
FOR SELECT TO authenticated
USING (
  org_id = public.get_user_org_id()
  OR
  EXISTS (
    SELECT 1 FROM leases
    WHERE leases.id = gateway_bills.lease_id
      AND leases.tenant_id = public.get_tenant_id()
  )
);

-- 10. Audit Log
-- Tenant: none. Staff: none. Manager: read own organization
-- Append-only trigger guarantees immutability
DROP POLICY IF EXISTS "audit_log_select" ON audit_log;
CREATE POLICY "audit_log_select" ON audit_log
FOR SELECT TO authenticated
USING (
  public.is_org_manager(org_id)
);

-- ─── 4. Storage Policies: payment-slips Bucket ──────────────────────────────
-- Bucket: 'payment-slips'
-- Paths: '<org_id>/...'
-- Access: Only staff and managers of that organization can upload and read.
-- Tenants, other orgs, and anon have NO access.

-- Enable RLS on storage.objects
ALTER TABLE storage.objects ENABLE ROW LEVEL SECURITY;

-- Allow Staff and Managers of an org to upload slips under their org folder
DROP POLICY IF EXISTS "slips_insert_policy" ON storage.objects;
CREATE POLICY "slips_insert_policy" ON storage.objects
FOR INSERT TO authenticated
WITH CHECK (
  bucket_id = 'payment-slips'
  AND public.get_user_role() IN ('manager', 'staff')
  AND public.extract_org_id_from_path(name) = public.get_user_org_id()
);

-- Allow Staff and Managers of an org to read slips from their org folder
DROP POLICY IF EXISTS "slips_select_policy" ON storage.objects;
CREATE POLICY "slips_select_policy" ON storage.objects
FOR SELECT TO authenticated
USING (
  bucket_id = 'payment-slips'
  AND public.get_user_role() IN ('manager', 'staff')
  AND public.extract_org_id_from_path(name) = public.get_user_org_id()
);

import { NextResponse } from 'next/server'
import { prisma } from '@/lib/prisma'
import { getAuthContext, jsonError } from '@/lib/auth'
import { generateSchedule } from '@/lib/billing'
import { Prisma } from '@/generated/prisma/client'

interface CreateLeaseBody {
  unitId: string
  tenantId: string
  startDate: string
  endDate: string
  monthlyRentSen: number
  depositSen: number
}

export async function POST(req: Request) {
  // 1. Authenticate and enforce manager role
  const auth = await getAuthContext(req)
  if (!auth) {
    return jsonError('Unauthorized', 401)
  }
  if (auth.role !== 'manager') {
    return jsonError('Forbidden: only managers can create leases', 403)
  }

  // 2. Parse and validate JSON input
  let body: CreateLeaseBody
  try {
    body = await req.json()
  } catch {
    return jsonError('Invalid JSON input', 400)
  }

  const { unitId, tenantId, startDate, endDate, monthlyRentSen, depositSen } = body

  if (
    !unitId ||
    !tenantId ||
    !startDate ||
    !endDate ||
    typeof monthlyRentSen !== 'number' ||
    typeof depositSen !== 'number'
  ) {
    return jsonError('Missing or invalid lease parameters', 400)
  }

  // 3. Verify unitId and tenantId belong to the caller's organization (return 404 to avoid leaking cross-org data)
  const unit = await prisma.unit.findFirst({
    where: { id: unitId, orgId: auth.orgId },
  })
  if (!unit) {
    return jsonError('Unit not found', 404)
  }

  const tenant = await prisma.tenant.findFirst({
    where: { id: tenantId, orgId: auth.orgId },
  })
  if (!tenant) {
    return jsonError('Tenant not found', 404)
  }

  // 4. Generate billing schedule using pure billing rules
  let schedule
  try {
    schedule = generateSchedule({
      startDate,
      endDate,
      monthlyRentSen,
      depositSen,
    })
  } catch (err: unknown) {
    const message = err instanceof Error ? err.message : 'Invalid lease dates or amounts'
    return jsonError(message, 400)
  }

  // 5. Atomic transaction: serialize on unit, check overlap, insert lease + invoices + audit_log
  try {
    const result = await prisma.$transaction(async (tx) => {
      // Row-level lock on the unit to serialize concurrent lease creation on the same unit
      await tx.$executeRaw`SELECT id FROM units WHERE id = ${unitId}::uuid FOR UPDATE`

      // Explicit check for overlapping leases on this unit
      // Both start_date and end_date are inclusive
      const overlapping = await tx.$queryRaw<{ id: string }[]>`
        SELECT id FROM leases
        WHERE unit_id = ${unitId}::uuid
          AND daterange(start_date, end_date, '[]') && daterange(${startDate}::date, ${endDate}::date, '[]')
        LIMIT 1
      `

      if (overlapping.length > 0) {
        throw new OverlapError('Lease overlaps with an existing lease on this unit')
      }

      // Create Lease
      const lease = await tx.lease.create({
        data: {
          orgId: auth.orgId,
          unitId,
          tenantId,
          startDate: new Date(`${startDate}T00:00:00.000Z`),
          endDate: new Date(`${endDate}T00:00:00.000Z`),
          monthlyRentSen: BigInt(monthlyRentSen),
          depositSen: BigInt(depositSen),
        },
      })

      // Create Invoices all-or-nothing
      await tx.invoice.createMany({
        data: schedule.map((inv) => ({
          orgId: auth.orgId,
          leaseId: lease.id,
          kind: inv.kind,
          periodIndex: inv.periodIndex,
          periodStart: inv.periodStart ? new Date(`${inv.periodStart}T00:00:00.000Z`) : null,
          periodEnd: inv.periodEnd ? new Date(`${inv.periodEnd}T00:00:00.000Z`) : null,
          dueDate: new Date(`${inv.dueDate}T00:00:00.000Z`),
          amountSen: BigInt(inv.amountSen),
        })),
      })

      // Audit Log
      await tx.auditLog.create({
        data: {
          orgId: auth.orgId,
          actorId: auth.userId,
          action: 'create_lease',
          entityId: lease.id,
          details: {
            unitId,
            tenantId,
            startDate,
            endDate,
            monthlyRentSen,
            depositSen,
            invoicesCount: schedule.length,
          },
        },
      })

      return lease
    })

    return NextResponse.json({ id: result.id }, { status: 201 })
  } catch (err: unknown) {
    if (err instanceof OverlapError) {
      return jsonError(err.message, 409)
    }

    // Catch Postgres GiST exclusion constraint error (code 23P01 or Prisma raw violation)
    if (err instanceof Prisma.PrismaClientKnownRequestError) {
      if (err.code === 'P2002' || (err.meta && String(err.meta.target).includes('gist'))) {
        return jsonError('Lease overlaps with an existing lease on this unit', 409)
      }
    }

    const message = err instanceof Error ? err.message : String(err)
    if (message.includes('conflicting key value violates exclusion constraint') || message.includes('23P01')) {
      return jsonError('Lease overlaps with an existing lease on this unit', 409)
    }

    console.error('Failed to create lease:', err)
    return jsonError('Internal server error', 500)
  }
}

class OverlapError extends Error {
  constructor(message: string) {
    super(message)
    this.name = 'OverlapError'
  }
}

import { NextResponse } from 'next/server'
import { prisma } from '@/lib/prisma'
import { getAuthContext, jsonError } from '@/lib/auth'
import { invoiceStatus, InvoiceStatus } from '@/lib/billing'

export async function GET(
  req: Request,
  { params }: { params: Promise<{ leaseId: string }> }
) {
  // 1. Authenticate caller
  const auth = await getAuthContext(req)
  if (!auth) {
    return jsonError('Unauthorized', 401)
  }

  const { leaseId } = await params

  // 2. Fetch the lease along with its invoices, allocations, and payments
  const lease = await prisma.lease.findUnique({
    where: { id: leaseId },
    include: {
      invoices: {
        include: {
          allocations: true,
        },
      },
      payments: true,
    },
  })

  // 3. Security & Multitenancy checks:
  // - If lease doesn't exist OR belongs to another organization: 404 (do not reveal existence)
  // - If tenant requests a lease belonging to another tenant: 404 (do not reveal existence)
  if (!lease || lease.orgId !== auth.orgId) {
    return jsonError('Lease not found', 404)
  }

  if (auth.role === 'tenant' && lease.tenantId !== auth.tenantId) {
    return jsonError('Lease not found', 404)
  }

  const now = new Date()

  // 4. Sort invoices in strict allocation order:
  // First by due date, then deposit before rent, then period index
  const sortedInvoices = [...lease.invoices].sort((a, b) => {
    const dueA = a.dueDate.toISOString().slice(0, 10)
    const dueB = b.dueDate.toISOString().slice(0, 10)
    if (dueA !== dueB) {
      return dueA.localeCompare(dueB)
    }

    if (a.kind !== b.kind) {
      return a.kind === 'deposit' ? -1 : 1
    }

    const pA = a.periodIndex ?? -1
    const pB = b.periodIndex ?? -1
    return pA - pB
  })

  // 5. Format invoices with dynamic paidSen and computed status
  const formattedInvoices = sortedInvoices.map((inv) => {
    const paidSen = inv.allocations.reduce((sum, alloc) => sum + Number(alloc.amountSen), 0)
    const dueDateStr = inv.dueDate.toISOString().slice(0, 10)
    const amountSen = Number(inv.amountSen)

    const status: InvoiceStatus = invoiceStatus(
      {
        dueDate: dueDateStr,
        amountSen,
        paidSen,
      },
      now
    )

    return {
      id: inv.id,
      kind: inv.kind,
      periodIndex: inv.periodIndex,
      periodStart: inv.periodStart ? inv.periodStart.toISOString().slice(0, 10) : null,
      periodEnd: inv.periodEnd ? inv.periodEnd.toISOString().slice(0, 10) : null,
      dueDate: dueDateStr,
      amountSen,
      paidSen,
      status,
    }
  })

  // 6. Format payments
  const formattedPayments = lease.payments.map((p) => ({
    id: p.id,
    amountSen: Number(p.amountSen),
    unappliedSen: Number(p.unappliedSen),
    method: p.method,
    status: p.status,
    receivedAt: p.receivedAt.toISOString(),
  }))

  // 7. Format lease
  const formattedLease = {
    id: lease.id,
    unitId: lease.unitId,
    tenantId: lease.tenantId,
    startDate: lease.startDate.toISOString().slice(0, 10),
    endDate: lease.endDate.toISOString().slice(0, 10),
    monthlyRentSen: Number(lease.monthlyRentSen),
    depositSen: Number(lease.depositSen),
  }

  return NextResponse.json({
    lease: formattedLease,
    invoices: formattedInvoices,
    payments: formattedPayments,
  })
}

