import { NextResponse } from 'next/server'
import { headers } from 'next/headers'
import { prisma } from '@/lib/prisma'
import { createClient } from '@/lib/supabase/server'
import { ROLES, AppRole } from '@/lib/constants'

export type UserRole = AppRole

export interface AuthContext {
  userId: string
  email: string
  role: AppRole
  orgId: string
  tenantId?: string // Defined only when role === ROLES.TENANT
}

/**
 * Standard JSON error response helper returning `{ "error": "message" }`.
 */
export function jsonError(message: string, status: number): NextResponse {
  return NextResponse.json({ error: message }, { status })
}

/**
 * Resolves the authenticated user and their validated role/organization from the database.
 * 
 * SECURITY RULES ENFORCED:
 * 1. Authenticates strictly with `supabase.auth.getUser()`, never `getSession()`.
 * 2. Accepts both cookies and `Authorization: Bearer <access_token>` headers.
 * 3. Roles and organization IDs are fetched strictly from `memberships` and `tenants` tables.
 *    `user_metadata` is NEVER used because the user could edit it.
 */
export async function getAuthContext(req?: Request): Promise<AuthContext | null> {
  const supabase = await createClient(req)

  // Check for Bearer token in request headers
  let bearerToken: string | undefined
  if (req) {
    const authHeader = req.headers.get('authorization')
    if (authHeader?.toLowerCase().startsWith('bearer ')) {
      bearerToken = authHeader.slice(7).trim()
    }
  } else {
    try {
      const h = await headers()
      const authHeader = h.get('authorization')
      if (authHeader?.toLowerCase().startsWith('bearer ')) {
        bearerToken = authHeader.slice(7).trim()
      }
    } catch {
      // ignore
    }
  }

  const { data: { user }, error } = bearerToken
    ? await supabase.auth.getUser(bearerToken)
    : await supabase.auth.getUser()

  if (error || !user) {
    return null
  }

  // 1. Check memberships (staff or manager)
  const membership = await prisma.membership.findUnique({
    where: { userId: user.id },
  })

  if (membership) {
    return {
      userId: user.id,
      email: user.email ?? '',
      role: membership.role as AppRole,
      orgId: membership.orgId,
    }
  }

  // 2. Check tenants (tenant role)
  const tenant = await prisma.tenant.findUnique({
    where: { userId: user.id },
  })

  if (tenant) {
    return {
      userId: user.id,
      email: user.email ?? '',
      role: ROLES.TENANT,
      orgId: tenant.orgId,
      tenantId: tenant.id,
    }
  }

  // User exists in auth.users but has no membership or tenant profile in the system
  return null
}

/**
 * Ensures the caller is authenticated and has one of the allowed roles.
 * Returns the AuthContext if valid, or a NextResponse error to return immediately.
 */
export async function requireAuth(
  req: Request | undefined,
  allowedRoles?: AppRole[]
): Promise<{ auth: AuthContext; errorResponse?: never } | { auth?: never; errorResponse: NextResponse }> {
  const auth = await getAuthContext(req)

  if (!auth) {
    return { errorResponse: jsonError('Unauthorized: missing or invalid credentials', 401) }
  }

  if (allowedRoles && !allowedRoles.includes(auth.role)) {
    return { errorResponse: jsonError('Forbidden: your role does not have permission for this action', 403) }
  }

  return { auth }
}

import { prisma } from '@/lib/prisma'
import { generateSchedule, invoiceStatus, InvoiceStatus } from '@/lib/billing'
import { AUDIT_ACTIONS, ROLES, AuthContext } from '@/lib/constants'
import { Prisma } from '@/generated/prisma/client'

export class OverlapError extends Error {
  constructor(message: string = 'Lease overlaps with an existing lease on this unit') {
    super(message)
    this.name = 'OverlapError'
  }
}

export class NotFoundError extends Error {
  constructor(message: string = 'Record not found') {
    super(message)
    this.name = 'NotFoundError'
  }
}

export class ValidationError extends Error {
  constructor(message: string) {
    super(message)
    this.name = 'ValidationError'
  }
}

export interface CreateLeaseInput {
  unitId: string
  tenantId: string
  startDate: string
  endDate: string
  monthlyRentSen: number
  depositSen: number
}

/**
 * Creates a lease and its invoices in an atomic, concurrency-safe transaction.
 */
export async function createLeaseService(auth: AuthContext, input: CreateLeaseInput) {
  const { unitId, tenantId, startDate, endDate, monthlyRentSen, depositSen } = input

  // 1. Validate caller is manager
  if (auth.role !== ROLES.MANAGER) {
    throw new ValidationError('Forbidden: only managers can create leases')
  }

  // 2. Validate unit belongs to caller's org
  const unit = await prisma.unit.findFirst({
    where: { id: unitId, orgId: auth.orgId },
  })
  if (!unit) {
    throw new NotFoundError('Unit not found')
  }

  // 3. Validate tenant belongs to caller's org
  const tenant = await prisma.tenant.findFirst({
    where: { id: tenantId, orgId: auth.orgId },
  })
  if (!tenant) {
    throw new NotFoundError('Tenant not found')
  }

  // 4. Generate schedule
  const schedule = generateSchedule({
    startDate,
    endDate,
    monthlyRentSen,
    depositSen,
  })

  // 5. Execute atomic transaction
  try {
    return await prisma.$transaction(async (tx) => {
      // Row-level lock on the unit
      await tx.$executeRaw`SELECT id FROM units WHERE id = ${unitId}::uuid FOR UPDATE`

      // Overlap check
      const overlapping = await tx.$queryRaw<{ id: string }[]>`
        SELECT id FROM leases
        WHERE unit_id = ${unitId}::uuid
          AND daterange(start_date, end_date, '[]') && daterange(${startDate}::date, ${endDate}::date, '[]')
        LIMIT 1
      `

      if (overlapping.length > 0) {
        throw new OverlapError()
      }

      // Insert lease
      const lease = await tx.lease.create({
        data: {
          orgId: auth.orgId,
          unitId,
          tenantId,
          startDate: new Date(`${startDate}T00:00:00.000Z`),
          endDate: new Date(`${endDate}T00:00:00.000Z`),
          monthlyRentSen: BigInt(monthlyRentSen),
          depositSen: BigInt(depositSen),
        },
      })

      // Insert invoices
      await tx.invoice.createMany({
        data: schedule.map((inv) => ({
          orgId: auth.orgId,
          leaseId: lease.id,
          kind: inv.kind,
          periodIndex: inv.periodIndex,
          periodStart: inv.periodStart ? new Date(`${inv.periodStart}T00:00:00.000Z`) : null,
          periodEnd: inv.periodEnd ? new Date(`${inv.periodEnd}T00:00:00.000Z`) : null,
          dueDate: new Date(`${inv.dueDate}T00:00:00.000Z`),
          amountSen: BigInt(inv.amountSen),
        })),
      })

      // Append to audit log
      await tx.auditLog.create({
        data: {
          orgId: auth.orgId,
          actorId: auth.userId,
          action: AUDIT_ACTIONS.CREATE_LEASE,
          entityId: lease.id,
          details: {
            unitId,
            tenantId,
            startDate,
            endDate,
            monthlyRentSen,
            depositSen,
            invoicesCount: schedule.length,
          },
        },
      })

      return lease
    })
  } catch (err: unknown) {
    if (err instanceof OverlapError) {
      throw err
    }
    if (err instanceof Prisma.PrismaClientKnownRequestError) {
      if (err.code === 'P2002' || (err.meta && String(err.meta.target).includes('gist'))) {
        throw new OverlapError()
      }
    }
    const msg = err instanceof Error ? err.message : String(err)
    if (msg.includes('conflicting key value violates exclusion constraint') || msg.includes('23P01')) {
      throw new OverlapError()
    }
    throw err
  }
}

/**
 * Retrieves a lease with dynamic invoice statuses and allocation ordering.
 */
export async function getLeaseDetailsService(auth: AuthContext, leaseId: string) {
  const lease = await prisma.lease.findUnique({
    where: { id: leaseId },
    include: {
      invoices: {
        include: {
          allocations: true,
        },
      },
      payments: true,
    },
  })

  // Multitenancy security checks
  if (!lease || lease.orgId !== auth.orgId) {
    throw new NotFoundError('Lease not found')
  }

  if (auth.role === ROLES.TENANT && lease.tenantId !== auth.tenantId) {
    throw new NotFoundError('Lease not found')
  }

  const now = new Date()

  // Sort invoices in allocation order: due date -> deposit before rent -> period index
  const sortedInvoices = [...lease.invoices].sort((a, b) => {
    const dueA = a.dueDate.toISOString().slice(0, 10)
    const dueB = b.dueDate.toISOString().slice(0, 10)
    if (dueA !== dueB) return dueA.localeCompare(dueB)

    if (a.kind !== b.kind) {
      return a.kind === 'deposit' ? -1 : 1
    }

    const pA = a.periodIndex ?? -1
    const pB = b.periodIndex ?? -1
    return pA - pB
  })

  const formattedInvoices = sortedInvoices.map((inv) => {
    const paidSen = inv.allocations.reduce((sum, alloc) => sum + Number(alloc.amountSen), 0)
    const dueDateStr = inv.dueDate.toISOString().slice(0, 10)
    const amountSen = Number(inv.amountSen)

    const status: InvoiceStatus = invoiceStatus(
      {
        dueDate: dueDateStr,
        amountSen,
        paidSen,
      },
      now
    )

    return {
      id: inv.id,
      kind: inv.kind,
      periodIndex: inv.periodIndex,
      periodStart: inv.periodStart ? inv.periodStart.toISOString().slice(0, 10) : null,
      periodEnd: inv.periodEnd ? inv.periodEnd.toISOString().slice(0, 10) : null,
      dueDate: dueDateStr,
      amountSen,
      paidSen,
      status,
    }
  })

  const formattedPayments = lease.payments.map((p) => ({
    id: p.id,
    amountSen: Number(p.amountSen),
    unappliedSen: Number(p.unappliedSen),
    method: p.method,
    status: p.status,
    receivedAt: p.receivedAt.toISOString(),
  }))

  const formattedLease = {
    id: lease.id,
    unitId: lease.unitId,
    tenantId: lease.tenantId,
    startDate: lease.startDate.toISOString().slice(0, 10),
    endDate: lease.endDate.toISOString().slice(0, 10),
    monthlyRentSen: Number(lease.monthlyRentSen),
    depositSen: Number(lease.depositSen),
  }

  return {
    lease: formattedLease,
    invoices: formattedInvoices,
    payments: formattedPayments,
  }
}

import { NextResponse } from 'next/server'
import { getAuthContext, jsonError } from '@/lib/auth'
import { ROLES } from '@/lib/constants'
import {
  createLeaseService,
  CreateLeaseInput,
  NotFoundError,
  OverlapError,
  ValidationError,
} from '@/lib/services/lease.service'

export async function POST(req: Request) {
  const auth = await getAuthContext(req)
  if (!auth) {
    return jsonError('Unauthorized', 401)
  }
  if (auth.role !== ROLES.MANAGER) {
    return jsonError('Forbidden: only managers can create leases', 403)
  }

  let body: CreateLeaseInput
  try {
    body = await req.json()
  } catch {
    return jsonError('Invalid JSON input', 400)
  }

  const { unitId, tenantId, startDate, endDate, monthlyRentSen, depositSen } = body
  if (
    !unitId ||
    !tenantId ||
    !startDate ||
    !endDate ||
    typeof monthlyRentSen !== 'number' ||
    typeof depositSen !== 'number'
  ) {
    return jsonError('Missing or invalid lease parameters', 400)
  }

  try {
    const lease = await createLeaseService(auth, body)
    return NextResponse.json({ id: lease.id }, { status: 201 })
  } catch (err: unknown) {
    if (err instanceof NotFoundError) {
      return jsonError(err.message, 404)
    }
    if (err instanceof OverlapError) {
      return jsonError(err.message, 409)
    }
    if (err instanceof ValidationError) {
      return jsonError(err.message, 400)
    }
    const message = err instanceof Error ? err.message : 'Invalid request'
    return jsonError(message, 400)
  }
}

