import { redirect } from 'next/navigation'
import { prisma } from '@/lib/prisma'
import { getAuthContext } from '@/lib/auth'
import { ROLES, BUSINESS_CONFIG } from '@/lib/constants'
import { getCollectionsReportService } from '@/lib/services/report.service'
import { invoiceStatus } from '@/lib/billing'
import { Navbar } from '@/components/navbar'
import { formatRinggit } from '@/lib/format-date'
import Link from 'next/link'
import { AlertCircle, TrendingUp, FileText, ArrowRight } from 'lucide-react'

export default async function DashboardPage() {
  const auth = await getAuthContext()
  if (!auth) {
    redirect('/login')
  }

  if (auth.role === ROLES.TENANT) {
    redirect('/tenant')
  }

  const organization = await prisma.organization.findUnique({
    where: { id: auth.orgId },
  })

  // 1. Calculate Overdue Invoices in this organization
  const now = new Date()
  const invoices = await prisma.invoice.findMany({
    where: { orgId: auth.orgId },
    include: { allocations: true },
  })

  let overdueCount = 0
  for (const inv of invoices) {
    const paidSen = inv.allocations.reduce((sum, a) => sum + Number(a.amountSen), 0)
    const dueDateStr = inv.dueDate.toISOString().slice(0, 10)
    const status = invoiceStatus(
      {
        dueDate: dueDateStr,
        amountSen: Number(inv.amountSen),
        paidSen,
      },
      now
    )
    if (status === 'overdue') {
      overdueCount++
    }
  }

  // 2. Compute 6-Month Range in Malaysia Time
  const mytNow = new Date(Date.now() + BUSINESS_CONFIG.UTC_OFFSET_MS)
  const endYear = mytNow.getUTCFullYear()
  const endMonth = mytNow.getUTCMonth() + 1 // 1-12

  // 5 months back to include exactly 6 months (e.g. Nov, Dec, Jan, Feb, Mar, Apr)
  let startYear = endYear
  let startMonth = endMonth - 5
  if (startMonth <= 0) {
    startMonth += 12
    startYear -= 1
  }

  const from = `${startYear}-${String(startMonth).padStart(2, '0')}`
  const to = `${endYear}-${String(endMonth).padStart(2, '0')}`

  const collections = await getCollectionsReportService(auth, from, to)
  const maxCollected = Math.max(...collections.map((c) => c.collectedSen), 1)
  const total6MonthCollected = collections.reduce((sum, c) => sum + c.collectedSen, 0)

  return (
    <div className="min-h-screen bg-slate-50">
      <Navbar
        userEmail={auth.email}
        role={auth.role}
        orgName={organization?.name ?? 'Organization'}
      />

      <main className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-8 space-y-8">
        <div>
          <h1 className="text-2xl font-bold tracking-tight text-slate-900">Collections Overview</h1>
          <p className="text-sm text-slate-500 mt-1">Real-time rent collection tracking and overdue invoice metrics.</p>
        </div>

        {/* Top Metric Cards */}
        <div className="grid grid-cols-1 sm:grid-cols-3 gap-5">
          <div className="bg-white p-6 rounded-2xl border border-slate-200 shadow-sm flex items-start justify-between">
            <div>
              <p className="text-xs font-semibold text-slate-500 uppercase tracking-wider">Overdue Invoices</p>
              <h3 className="text-3xl font-extrabold text-slate-900 mt-2">{overdueCount}</h3>
              <p className="text-xs text-slate-500 mt-1">Requiring immediate tenant follow-up</p>
            </div>
            <div className={`p-3 rounded-xl ${overdueCount > 0 ? 'bg-red-50 text-red-600' : 'bg-emerald-50 text-emerald-600'}`}>
              <AlertCircle className="w-6 h-6" />
            </div>
          </div>

          <div className="bg-white p-6 rounded-2xl border border-slate-200 shadow-sm flex items-start justify-between">
            <div>
              <p className="text-xs font-semibold text-slate-500 uppercase tracking-wider">6-Month Total Collected</p>
              <h3 className="text-3xl font-extrabold text-slate-900 mt-2">{formatRinggit(total6MonthCollected)}</h3>
              <p className="text-xs text-slate-500 mt-1">Approved payments across all leases</p>
            </div>
            <div className="p-3 bg-indigo-50 text-indigo-600 rounded-xl">
              <TrendingUp className="w-6 h-6" />
            </div>
          </div>

          <div className="bg-white p-6 rounded-2xl border border-slate-200 shadow-sm flex items-start justify-between">
            <div>
              <p className="text-xs font-semibold text-slate-500 uppercase tracking-wider">Active Leases</p>
              <h3 className="text-3xl font-extrabold text-slate-900 mt-2">
                <Link href="/leases" className="hover:text-indigo-600 transition flex items-center gap-1.5">
                  Manage Leases
                  <ArrowRight className="w-5 h-5 inline text-slate-400" />
                </Link>
              </h3>
              <p className="text-xs text-slate-500 mt-1">Record payments and review schedules</p>
            </div>
            <div className="p-3 bg-slate-100 text-slate-700 rounded-xl">
              <FileText className="w-6 h-6" />
            </div>
          </div>
        </div>

        {/* 6-Month Collections Chart / Table */}
        <div className="bg-white p-6 rounded-2xl border border-slate-200 shadow-sm space-y-6">
          <div className="flex items-center justify-between">
            <div>
              <h2 className="text-lg font-bold text-slate-900">Collections by Month (MYT)</h2>
              <p className="text-xs text-slate-500 mt-0.5">Approved rent & deposit receipts ({from} to {to})</p>
            </div>
          </div>

          <div className="grid grid-cols-2 sm:grid-cols-6 gap-4 pt-2">
            {collections.map((item) => {
              const heightPercent = Math.round((item.collectedSen / maxCollected) * 100)
              return (
                <div key={item.month} className="flex flex-col items-center bg-slate-50/70 p-4 rounded-xl border border-slate-100">
                  <div className="w-full h-32 flex items-end justify-center mb-3">
                    <div
                      style={{ height: `${Math.max(heightPercent, 4)}%` }}
                      className={`w-10 rounded-t-lg transition-all duration-500 ${
                        item.collectedSen > 0 ? 'bg-slate-900' : 'bg-slate-200'
                      }`}
                    />
                  </div>
                  <span className="text-xs font-mono font-bold text-slate-900">{formatRinggit(item.collectedSen)}</span>
                  <span className="text-[11px] font-medium text-slate-500 mt-1">{item.month}</span>
                </div>
              )
            })}
          </div>
        </div>
      </main>
    </div>
  )
}

'use client'

import { useState } from 'react'
import { createClient } from '@/lib/supabase/client'
import { STORAGE } from '@/lib/constants'
import { toast } from 'sonner'
import { FileText, ExternalLink } from 'lucide-react'

export function SlipLink({ slipPath }: { slipPath: string | null }) {
  const [loading, setLoading] = useState(false)

  if (!slipPath) return null

  async function handleOpenSlip() {
    setLoading(true)
    try {
      const supabase = createClient()
      const { data, error } = await supabase.storage
        .from(STORAGE.PAYMENT_SLIPS_BUCKET)
        .createSignedUrl(slipPath, 60) // 60-second signed URL

      if (error || !data?.signedUrl) {
        toast.error('Unable to generate secure slip URL')
        return
      }

      window.open(data.signedUrl, '_blank')
    } catch {
      toast.error('Failed to open slip file')
    } finally {
      setLoading(false)
    }
  }

  return (
    <button
      type="button"
      onClick={handleOpenSlip}
      disabled={loading}
      className="inline-flex items-center gap-1.5 text-xs font-medium text-indigo-600 hover:text-indigo-800 transition disabled:opacity-50"
    >
      <FileText className="w-3.5 h-3.5" />
      {loading ? 'Opening...' : 'View Slip'}
      <ExternalLink className="w-3 h-3" />
    </button>
  )
}

import { createBrowserClient } from '@supabase/ssr'

/**
 * Creates a browser-side Supabase client using publishable anon key.
 * Used for direct client operations (signed slip URLs, tenant portal reads/updates).
 */
export function createClient() {
  return createBrowserClient(
    process.env.NEXT_PUBLIC_SUPABASE_URL!,
    process.env.NEXT_PUBLIC_SUPABASE_ANON_KEY!
  )
}

'use client'

import { useState } from 'react'
import { useRouter } from 'next/navigation'
import { parseRinggitToSen } from '@/lib/billing'
import { createClient } from '@/lib/supabase/client'
import { PaymentMethod, STORAGE } from '@/lib/constants'
import { toast } from 'sonner'
import { Plus, X, Upload } from 'lucide-react'

interface RecordPaymentModalProps {
  leaseId: string
  orgId: string
  userRole: string
}

export function RecordPaymentModal({ leaseId, orgId, userRole }: RecordPaymentModalProps) {
  const [open, setOpen] = useState(false)
  const [amountInput, setAmountInput] = useState('')
  const [method, setMethod] = useState<PaymentMethod>(PaymentMethod.cash)
  const [receivedAt, setReceivedAt] = useState(() => {
    // Current Malaysia time formatted for datetime-local input
    const nowMyt = new Date(Date.now() + 8 * 3600 * 1000)
    return nowMyt.toISOString().slice(0, 16)
  })
  const [file, setFile] = useState<File | null>(null)
  const [loading, setLoading] = useState(false)
  const router = useRouter()

  async function handleSubmit(e: React.FormEvent<HTMLFormElement>) {
    e.preventDefault()
    setLoading(true)

    // 1. Parse ringgit using pure billing function
    let amountSen: number
    try {
      amountSen = parseRinggitToSen(amountInput)
    } catch (err: unknown) {
      toast.error(err instanceof Error ? err.message : 'Invalid ringgit amount format')
      setLoading(false)
      return
    }

    if (amountSen <= 0) {
      toast.error('Payment amount must be greater than zero')
      setLoading(false)
      return
    }

    // 2. Handle file upload for bank transfer
    let slipPath: string | undefined
    if (method === PaymentMethod.bank_transfer) {
      if (!file) {
        toast.error('Please upload a bank transfer slip (JPEG, PNG or PDF under 5MB)')
        setLoading(false)
        return
      }

      if (file.size > STORAGE.MAX_SLIP_SIZE_BYTES) {
        toast.error('Slip file exceeds 5MB limit')
        setLoading(false)
        return
      }

      try {
        const supabase = createClient()
        const fileExt = file.name.split('.').pop()
        const fileName = `${Date.now()}-${Math.random().toString(36).slice(2, 8)}.${fileExt}`
        const storagePath = `${orgId}/slips/${fileName}`

        const { error: uploadError } = await supabase.storage
          .from(STORAGE.PAYMENT_SLIPS_BUCKET)
          .upload(storagePath, file, { contentType: file.type })

        if (uploadError) {
          toast.error(`Slip upload failed: ${uploadError.message}`)
          setLoading(false)
          return
        }

        slipPath = storagePath
      } catch {
        toast.error('Network error during slip upload')
        setLoading(false)
        return
      }
    }

    // 3. Post to payment API with UUID idempotency key
    const idempotencyKey = crypto.randomUUID()
    const receivedAtIso = `${receivedAt}:00+08:00` // Explicit Malaysia offset

    try {
      const res = await fetch(`/api/leases/${leaseId}/payments`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'Idempotency-Key': idempotencyKey,
        },
        body: JSON.stringify({
          amountSen,
          method,
          receivedAt: receivedAtIso,
          slipPath,
        }),
      })

      const data = await res.json()

      if (!res.ok) {
        toast.error(data.error || 'Failed to record payment')
        setLoading(false)
        return
      }

      toast.success(
        data.status === 'approved'
          ? 'Payment recorded and approved immediately!'
          : 'Payment recorded! Awaiting manager verification.'
      )
      setOpen(false)
      setAmountInput('')
      setFile(null)
      router.refresh()
    } catch {
      toast.error('Failed to submit payment request')
    } finally {
      setLoading(false)
    }
  }

  return (
    <>
      <button
        type="button"
        onClick={() => setOpen(true)}
        className="inline-flex items-center gap-2 px-4 py-2 bg-slate-900 hover:bg-slate-800 text-white rounded-lg text-sm font-medium transition shadow-sm"
      >
        <Plus className="w-4 h-4" />
        Record Payment
      </button>

      {open && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-slate-900/40 backdrop-blur-xs">
          <div className="bg-white rounded-2xl max-w-md w-full p-6 shadow-xl border border-slate-200">
            <div className="flex items-center justify-between pb-4 border-b border-slate-100">
              <h3 className="text-base font-bold text-slate-900">Record Lease Payment</h3>
              <button
                type="button"
                onClick={() => setOpen(false)}
                className="text-slate-400 hover:text-slate-600 rounded-lg p-1"
              >
                <X className="w-5 h-5" />
              </button>
            </div>

            <form onSubmit={handleSubmit} className="mt-5 space-y-4">
              <div>
                <label className="block text-xs font-semibold text-slate-600 uppercase mb-1">
                  Amount in Ringgit (e.g. 1,500.00)
                </label>
                <input
                  type="text"
                  value={amountInput}
                  onChange={(e) => setAmountInput(e.target.value)}
                  placeholder="1,500.00"
                  required
                  className="w-full px-3 py-2 text-sm border border-slate-200 rounded-lg focus:outline-none focus:ring-2 focus:ring-slate-900/10 focus:border-slate-900 font-mono"
                />
              </div>

              <div>
                <label className="block text-xs font-semibold text-slate-600 uppercase mb-1">Payment Method</label>
                <div className="grid grid-cols-2 gap-2">
                  <button
                    type="button"
                    onClick={() => setMethod(PaymentMethod.cash)}
                    className={`py-2 text-xs font-medium rounded-lg border transition ${
                      method === PaymentMethod.cash
                        ? 'bg-slate-900 text-white border-slate-900'
                        : 'bg-white text-slate-600 border-slate-200 hover:bg-slate-50'
                    }`}
                  >
                    Cash
                  </button>
                  <button
                    type="button"
                    onClick={() => setMethod(PaymentMethod.bank_transfer)}
                    className={`py-2 text-xs font-medium rounded-lg border transition ${
                      method === PaymentMethod.bank_transfer
                        ? 'bg-slate-900 text-white border-slate-900'
                        : 'bg-white text-slate-600 border-slate-200 hover:bg-slate-50'
                    }`}
                  >
                    Bank Transfer
                  </button>
                </div>
              </div>

              <div>
                <label className="block text-xs font-semibold text-slate-600 uppercase mb-1">
                  Received Date & Time (Malaysia Time)
                </label>
                <input
                  type="datetime-local"
                  value={receivedAt}
                  onChange={(e) => setReceivedAt(e.target.value)}
                  required
                  className="w-full px-3 py-2 text-sm border border-slate-200 rounded-lg focus:outline-none focus:ring-2 focus:ring-slate-900/10 focus:border-slate-900"
                />
              </div>

              {method === PaymentMethod.bank_transfer && (
                <div>
                  <label className="block text-xs font-semibold text-slate-600 uppercase mb-1">
                    Transfer Slip (JPEG, PNG, PDF ≤ 5MB)
                  </label>
                  <div className="relative border border-dashed border-slate-300 rounded-lg p-4 text-center hover:bg-slate-50 transition">
                    <input
                      type="file"
                      accept="image/png,image/jpeg,application/pdf"
                      onChange={(e) => setFile(e.target.files?.[0] || null)}
                      required
                      className="absolute inset-0 w-full h-full opacity-0 cursor-pointer"
                    />
                    <Upload className="w-5 h-5 text-slate-400 mx-auto mb-1" />
                    <span className="text-xs text-slate-600 block truncate">
                      {file ? file.name : 'Choose file or drag & drop'}
                    </span>
                  </div>
                </div>
              )}

              <div className="pt-2 flex justify-end gap-2">
                <button
                  type="button"
                  onClick={() => setOpen(false)}
                  className="px-4 py-2 text-sm font-medium text-slate-600 hover:bg-slate-100 rounded-lg transition"
                >
                  Cancel
                </button>
                <button
                  type="submit"
                  disabled={loading}
                  className="px-4 py-2 text-sm font-medium bg-slate-900 hover:bg-slate-800 text-white rounded-lg transition disabled:opacity-50"
                >
                  {loading ? 'Recording...' : userRole === 'manager' ? 'Record & Approve' : 'Submit for Verification'}
                </button>
              </div>
            </form>
          </div>
        </div>
      )}
    </>
  )
}

'use client'

import { useState } from 'react'
import { useRouter } from 'next/navigation'
import { toast } from 'sonner'
import { Check, X, Ban } from 'lucide-react'

interface ManagerActionsProps {
  paymentId: string
  status: string
  isManager: boolean
}

export function ManagerActions({ paymentId, status, isManager }: ManagerActionsProps) {
  const [modalType, setModalType] = useState<'reject' | 'void' | null>(null)
  const [reason, setReason] = useState('')
  const [loading, setLoading] = useState(false)
  const router = useRouter()

  if (!isManager) {
    return null
  }

  async function handleApprove() {
    setLoading(true)
    try {
      const res = await fetch(`/api/payments/${paymentId}/approve`, {
        method: 'POST',
      })
      const data = await res.json()
      if (!res.ok) {
        toast.error(data.error || 'Failed to approve payment')
        return
      }
      toast.success('Payment approved and allocated successfully!')
      router.refresh()
    } catch {
      toast.error('Network error during payment approval')
    } finally {
      setLoading(false)
    }
  }

  async function handleReasonSubmit(e: React.FormEvent<HTMLFormElement>) {
    e.preventDefault()
    if (!reason || reason.trim().length < 5) {
      toast.error('Reason must be at least 5 characters')
      return
    }

    setLoading(true)
    const endpoint = modalType === 'reject' ? 'reject' : 'void'

    try {
      const res = await fetch(`/api/payments/${paymentId}/${endpoint}`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ reason: reason.trim() }),
      })
      const data = await res.json()

      if (!res.ok) {
        toast.error(data.error || `Failed to ${endpoint} payment`)
        return
      }

      toast.success(`Payment ${endpoint}ed successfully`)
      setModalType(null)
      setReason('')
      router.refresh()
    } catch {
      toast.error(`Network error during payment ${endpoint}`)
    } finally {
      setLoading(false)
    }
  }

  return (
    <>
      <div className="flex items-center gap-1.5 justify-end">
        {status === 'pending_verification' && (
          <>
            <button
              type="button"
              onClick={handleApprove}
              disabled={loading}
              className="inline-flex items-center gap-1 px-2.5 py-1 text-xs font-semibold rounded-md bg-emerald-50 text-emerald-700 hover:bg-emerald-100 border border-emerald-200 transition disabled:opacity-50"
            >
              <Check className="w-3.5 h-3.5" />
              Approve
            </button>
            <button
              type="button"
              onClick={() => {
                setModalType('reject')
                setReason('')
              }}
              disabled={loading}
              className="inline-flex items-center gap-1 px-2.5 py-1 text-xs font-semibold rounded-md bg-red-50 text-red-700 hover:bg-red-100 border border-red-200 transition disabled:opacity-50"
            >
              <X className="w-3.5 h-3.5" />
              Reject
            </button>
          </>
        )}

        {status === 'approved' && (
          <button
            type="button"
            onClick={() => {
              setModalType('void')
              setReason('')
            }}
            disabled={loading}
            className="inline-flex items-center gap-1 px-2.5 py-1 text-xs font-semibold rounded-md bg-slate-100 text-slate-700 hover:bg-slate-200 border border-slate-300 transition disabled:opacity-50"
          >
            <Ban className="w-3.5 h-3.5" />
            Void
          </button>
        )}
      </div>

      {modalType && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-slate-900/40 backdrop-blur-xs">
          <div className="bg-white rounded-2xl max-w-sm w-full p-6 shadow-xl border border-slate-200">
            <h3 className="text-base font-bold text-slate-900 capitalize">
              {modalType === 'reject' ? 'Reject Payment' : 'Confirm Payment Void'}
            </h3>
            <p className="text-xs text-slate-500 mt-1">
              {modalType === 'reject'
                ? 'Please provide a clear reason for rejecting this verification request.'
                : 'Voiding this payment will remove all its allocations across invoices.'}
            </p>

            <form onSubmit={handleReasonSubmit} className="mt-4 space-y-3">
              <div>
                <label className="block text-xs font-semibold text-slate-600 uppercase mb-1">
                  Reason (min 5 characters)
                </label>
                <textarea
                  value={reason}
                  onChange={(e) => setReason(e.target.value)}
                  placeholder="Enter detailed audit reason..."
                  required
                  minLength={5}
                  rows={3}
                  className="w-full px-3 py-2 text-sm border border-slate-200 rounded-lg focus:outline-none focus:ring-2 focus:ring-slate-900/10 focus:border-slate-900"
                />
              </div>

              <div className="flex justify-end gap-2 pt-2">
                <button
                  type="button"
                  onClick={() => setModalType(null)}
                  className="px-3 py-1.5 text-xs font-medium text-slate-600 hover:bg-slate-100 rounded-lg transition"
                >
                  Cancel
                </button>
                <button
                  type="submit"
                  disabled={loading || reason.trim().length < 5}
                  className={`px-3 py-1.5 text-xs font-medium text-white rounded-lg transition disabled:opacity-50 ${
                    modalType === 'reject' ? 'bg-red-600 hover:bg-red-700' : 'bg-slate-900 hover:bg-slate-800'
                  }`}
                >
                  {loading ? 'Processing...' : modalType === 'reject' ? 'Reject Payment' : 'Confirm Void'}
                </button>
              </div>
            </form>
          </div>
        </div>
      )}
    </>
  )
}

