  // 3. Create Tenants
  console.log('Creating tenants...')

  // Aisyah Rahman (Northwind)
  const aisyahUser = await getOrCreateAuthUser(adminClient, 'aisyah@northwind.test')
  const aisyahTenant = await prisma.tenant.upsert({
    where: { userId: aisyahUser.id },
